//! Minimal GLB (binary glTF 2.0) writer.
//!
//! Mirrors the reference `rvm2glb` export contract: **POSITION-only** triangle
//! meshes (no normals — face normals are regenerated by viewers), one
//! `material` per mesh (PBR `baseColorFactor`). Each `MeshPart` carries an
//! ancestor `path`; the writer rebuilds the scene-graph **node tree** from those
//! paths (intermediate group nodes + mesh leaves), so the output nests under the
//! site roots like the source — navigable, not flat.
//!
//! A GLB is: a 12-byte header, a JSON chunk, then a BIN chunk. We hand-write
//! the JSON (no serde dependency) and pack all geometry into one binary buffer.

use std::sync::Arc;

/// A part's world-space positions. Most placements are INSTANCES of a shared
/// geometry-record prototype at a translation — storing the prototype once
/// (`Arc`) and materializing points only while writing keeps large models
/// (100k+ instances) in memory: owned copies of every instance's vertices is
/// what used to OOM on real plant files.
#[derive(Clone)]
pub enum PartPositions {
    Owned(Vec<[f32; 3]>),
    /// `proto` is the record's LOCAL native-space mesh; each point materializes
    /// as `(p + t)` in native f64, then native→glTF `(x, z, -y)` — bit-exact
    /// with the historical eager path.
    Instanced {
        proto: Arc<Vec<[f32; 3]>>,
        t: [f64; 3],
    },
    /// A shared prototype under a full similarity transform:
    /// `world = R(q)·(s·p) + t` (q = xyzw quaternion, s = signed uniform
    /// scale), then native→glTF. The interned placement stream's form
    /// (Revit / DWG / 3DS loaders); one prototype serves every instance.
    Placed {
        proto: Arc<Vec<[f32; 3]>>,
        q: [f64; 4],
        s: f64,
        t: [f64; 3],
    },
    /// Parametric cylinder: LOCAL caps `a`/`b` + radius, at native translation
    /// `t`. Vertices generate at write time (32 points; the index topology is
    /// fixed — see `convert::cyl_idx`).
    Cyl {
        a: [f32; 3],
        b: [f32; 3],
        r: f32,
        t: [f64; 3],
    },
    /// AUX parametric primitive (disc / open tube) at native translation `t`,
    /// tessellated exactly as Navisworks does (`geometry::aux_points`).
    Aux {
        prim: crate::geometry::AuxPrim,
        t: [f64; 3],
    },
    /// Placeholder box from a LOCAL AABB (thickened to `th`), at native
    /// translation `t`. 8 points, fixed topology.
    Boxed {
        mn: [f32; 3],
        mx: [f32; 3],
        th: f32,
        t: [f64; 3],
    },
    /// X-cross line proxy between two glTF-space WORLD points. 8 points,
    /// fixed topology (empty if the segment is degenerate).
    Cross {
        a: [f32; 3],
        b: [f32; 3],
        w: f32,
    },
}

/// native (p + t) → glTF `(x, z, -y)`, f64 addition (bit-exact with the
/// historical eager `place`).
fn place_pt(p: [f32; 3], t: &[f64; 3]) -> [f32; 3] {
    [
        (p[0] as f64 + t[0]) as f32,
        (p[2] as f64 + t[2]) as f32,
        -((p[1] as f64 + t[1]) as f32),
    ]
}

/// `R(q)·(s·p) + t` in f64, then native → glTF `(x, z, -y)`.
pub fn place_xf(p: &[f32; 3], q: &[f64; 4], s: f64, t: &[f64; 3]) -> [f32; 3] {
    let v = glam::DVec3::new(p[0] as f64, p[1] as f64, p[2] as f64) * s;
    let w = glam::DQuat::from_xyzw(q[0], q[1], q[2], q[3]) * v + glam::DVec3::from_array(*t);
    [w.x as f32, w.z as f32, -(w.y as f32)]
}

impl PartPositions {
    pub fn len(&self) -> usize {
        match self {
            PartPositions::Owned(v) => v.len(),
            PartPositions::Instanced { proto, .. } | PartPositions::Placed { proto, .. } => {
                proto.len()
            }
            PartPositions::Cyl { .. } => 32, // 2 rings × 16 segments
            PartPositions::Aux { prim, .. } => match prim {
                crate::geometry::AuxPrim::Disc { .. } => crate::geometry::AUX_SEGMENTS + 1,
                crate::geometry::AuxPrim::Cyl { .. } => 2 * crate::geometry::AUX_SEGMENTS,
            },
            PartPositions::Boxed { .. } => 8,
            PartPositions::Cross { a, b, .. } => {
                let d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
                if (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt() < 1e-6 {
                    0
                } else {
                    8
                }
            }
        }
    }
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
    /// Materialized world-space (glTF) points. Borrowed for `Owned`; generated
    /// transiently for the deferred variants (the whole point: nothing is held
    /// per instance between placement and write).
    pub fn points(&self) -> std::borrow::Cow<'_, [[f32; 3]]> {
        use std::borrow::Cow;
        match self {
            PartPositions::Owned(v) => Cow::Borrowed(v.as_slice()),
            PartPositions::Instanced { proto, t } => {
                Cow::Owned(proto.iter().map(|&p| place_pt(p, t)).collect())
            }
            PartPositions::Placed { proto, q, s, t } => {
                Cow::Owned(proto.iter().map(|p| place_xf(p, q, *s, t)).collect())
            }
            PartPositions::Cyl { a, b, r, t } => {
                let (pos, _) = crate::geometry::cylinder_mesh(*a, *b, *r);
                Cow::Owned(pos.into_iter().map(|p| place_pt(p, t)).collect())
            }
            PartPositions::Boxed { mn, mx, th, t } => {
                let (pos, _) = crate::geometry::box_mesh(*mn, *mx, *th);
                Cow::Owned(pos.into_iter().map(|p| place_pt(p, t)).collect())
            }
            PartPositions::Aux { prim, t } => Cow::Owned(
                crate::geometry::aux_points(prim)
                    .into_iter()
                    .map(|p| place_pt(p, t))
                    .collect(),
            ),
            PartPositions::Cross { a, b, w } => {
                let (pos, _) = crate::geometry::cross_mesh(*a, *b, *w);
                Cow::Owned(pos)
            }
        }
    }
    /// Append the materialized world-space (glTF) points to `out` — same values
    /// as [`points`], without a per-part allocation for the instanced variant
    /// (the bulk of a plant model).
    pub fn extend_points(&self, out: &mut Vec<[f32; 3]>) {
        match self {
            PartPositions::Owned(v) => out.extend_from_slice(v),
            PartPositions::Instanced { proto, t } => {
                out.extend(proto.iter().map(|&p| place_pt(p, t)))
            }
            PartPositions::Placed { proto, q, s, t } => {
                out.extend(proto.iter().map(|p| place_xf(p, q, *s, t)))
            }
            other => out.extend_from_slice(&other.points()),
        }
    }
    /// The world-space (glTF) point at index `i` (O(n) for deferred variants —
    /// only used on tiny 2-point line records).
    pub fn at(&self, i: usize) -> [f32; 3] {
        match self {
            PartPositions::Owned(v) => v[i],
            PartPositions::Instanced { proto, t } => place_pt(proto[i], t),
            _ => self.points()[i],
        }
    }
}

impl From<Vec<[f32; 3]>> for PartPositions {
    fn from(v: Vec<[f32; 3]>) -> Self {
        PartPositions::Owned(v)
    }
}

/// One primitive to emit: world-space positions + u32 indices + a name/colour.
#[derive(Clone)]
pub struct MeshPart {
    pub name: String,
    pub positions: PartPositions,
    pub indices: Arc<Vec<u32>>,
    /// glTF primitive mode: 4 = TRIANGLES (default), 1 = LINES.
    pub mode: u32,
    /// Linear RGBA in 0..1.
    pub color: [f32; 4],
    /// Ancestor node names (root → this mesh). When present across parts, the
    /// writer rebuilds the scene-graph tree; empty = flat (scene-root) node.
    pub path: Vec<String>,
}

pub const MODE_TRIANGLES: u32 = 4;
pub const MODE_LINES: u32 = 1;

/// Writer-side post-processing options (rvm2glb contract).
#[derive(Clone, Copy, Debug)]
pub struct GlbOptions {
    pub include_normals: bool,
    pub cleanup_position: bool,
    pub cleanup_precision: u8,
    pub meshopt_threshold: f32,
    pub meshopt_target_error: f32,
    /// Uniform factor, model units → output units (metres), applied to every
    /// part's world-space points as they are materialized for writing — so
    /// the weld grid (`cleanup_precision`), the simplifier and the accessor /
    /// returned bounds all work in OUTPUT units. `1.0` leaves the points
    /// untouched (bit-exact with the unscaled writer).
    pub unit_scale: f32,
}

impl Default for GlbOptions {
    fn default() -> Self {
        GlbOptions {
            include_normals: false,
            cleanup_position: true,
            cleanup_precision: 3,
            meshopt_threshold: 0.75,
            meshopt_target_error: 0.0,
            unit_scale: 1.0,
        }
    }
}

impl GlbOptions {
    /// A model-unit bbox in output units (`unit_scale` is positive, so the
    /// corners keep their roles; an empty ±inf box stays empty).
    pub fn scale_bbox(&self, mn: [f32; 3], mx: [f32; 3]) -> ([f32; 3], [f32; 3]) {
        if self.unit_scale == 1.0 {
            return (mn, mx);
        }
        (
            mn.map(|v| v * self.unit_scale),
            mx.map(|v| v * self.unit_scale),
        )
    }
}

/// Reusable scratch for [`finalize_append`] (one per worker thread): the
/// materialized points, the weld's open-addressing table and the part-local
/// index list. Reused across parts so finalizing 100k+ small parts does not
/// allocate per part.
#[derive(Default)]
struct Weld {
    pts: Vec<[f32; 3]>,
    remap: Vec<u32>,
    /// Open-addressing table: 0 = empty, else (welded vertex index + 1).
    slots: Vec<u32>,
    keys: Vec<[i64; 3]>,
    idx: Vec<u32>,
}

#[inline]
fn weld_hash(k: &[i64; 3]) -> usize {
    // Fx-style multiplicative mix — the keys are small grid integers, so a
    // cryptographic hash (std's SipHash) is pure overhead here.
    const M: u64 = 0x9E37_79B9_7F4A_7C15;
    let mut h = (k[0] as u64).wrapping_mul(M);
    h = (h.rotate_left(23) ^ (k[1] as u64)).wrapping_mul(M);
    h = (h.rotate_left(23) ^ (k[2] as u64)).wrapping_mul(M);
    (h ^ (h >> 29)) as usize
}

/// Materialize a part's final geometry and APPEND it to `pos` / `idx`
/// (indices are rebased onto `pos`, i.e. offset by its length on entry): scale
/// the points to output units (`unit_scale` — the ONE place the unit factor
/// touches geometry; every writer comes through here), weld
/// coincident vertices on a 10^-precision grid, keeping the first occurrence
/// (dropping triangles degenerated by the weld), optional meshopt
/// simplification (feature `optimize`), optional area-weighted smooth
/// per-vertex normals (appended to `norm`, triangle parts only).
/// Returns the number of indices appended.
fn finalize_append(
    part: &MeshPart,
    o: &GlbOptions,
    w: &mut Weld,
    pos: &mut Vec<[f32; 3]>,
    idx: &mut Vec<u32>,
    norm: Option<&mut Vec<[f32; 3]>>,
) -> usize {
    w.pts.clear();
    part.positions.extend_points(&mut w.pts);
    if o.unit_scale != 1.0 {
        for p in w.pts.iter_mut() {
            *p = p.map(|v| v * o.unit_scale);
        }
    }
    w.idx.clear();
    let p0 = pos.len();
    if o.cleanup_position && !w.pts.is_empty() {
        let scale = 10f64.powi(o.cleanup_precision as i32) as f32;
        let cap = (w.pts.len() * 2).next_power_of_two().max(16);
        let mask = cap - 1;
        w.slots.clear();
        w.slots.resize(cap, 0);
        w.keys.clear();
        w.remap.clear();
        for p in &w.pts {
            let k = [
                (p[0] * scale).round() as i64,
                (p[1] * scale).round() as i64,
                (p[2] * scale).round() as i64,
            ];
            let mut h = weld_hash(&k) & mask;
            let e = loop {
                let slot = w.slots[h];
                if slot == 0 {
                    w.keys.push(k);
                    pos.push(*p);
                    w.slots[h] = w.keys.len() as u32;
                    break w.keys.len() as u32 - 1;
                }
                if w.keys[slot as usize - 1] == k {
                    break slot - 1;
                }
                h = (h + 1) & mask;
            };
            w.remap.push(e);
        }
        if part.mode == MODE_TRIANGLES {
            for t in part.indices.chunks_exact(3) {
                let (a, b, c) = (
                    w.remap[t[0] as usize],
                    w.remap[t[1] as usize],
                    w.remap[t[2] as usize],
                );
                if a != b && b != c && a != c {
                    w.idx.extend_from_slice(&[a, b, c]);
                }
            }
        } else {
            w.idx
                .extend(part.indices.iter().map(|&i| w.remap[i as usize]));
        }
    } else {
        pos.extend_from_slice(&w.pts);
        w.idx.extend_from_slice(&part.indices);
    }
    #[cfg(feature = "optimize")]
    if o.meshopt_threshold < 1.0 && part.mode == MODE_TRIANGLES && w.idx.len() >= 12 {
        let target = ((w.idx.len() as f32 * o.meshopt_threshold) as usize / 3) * 3;
        let local = &pos[p0..];
        let bytes: &[u8] =
            unsafe { std::slice::from_raw_parts(local.as_ptr() as *const u8, local.len() * 12) };
        if let Ok(adapter) = meshopt::VertexDataAdapter::new(bytes, 12, 0) {
            w.idx = meshopt::simplify(
                &w.idx,
                &adapter,
                target.max(3),
                o.meshopt_target_error,
                meshopt::SimplifyOptions::None,
                None,
            );
        }
    }
    #[cfg(not(feature = "optimize"))]
    let _ = (o.meshopt_threshold, o.meshopt_target_error);
    if let (Some(norm), true) = (norm, part.mode == MODE_TRIANGLES) {
        // Area-weighted smooth normals: accumulate un-normalized face cross
        // products per vertex, normalize at the end.
        let local = &pos[p0..];
        let n0 = norm.len();
        norm.resize(n0 + local.len(), [0.0f32; 3]);
        let n = &mut norm[n0..];
        for t in w.idx.chunks_exact(3) {
            let (a, b, c) = (
                local[t[0] as usize],
                local[t[1] as usize],
                local[t[2] as usize],
            );
            let u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
            let v = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
            let f = [
                u[1] * v[2] - u[2] * v[1],
                u[2] * v[0] - u[0] * v[2],
                u[0] * v[1] - u[1] * v[0],
            ];
            for &vi in t {
                for k in 0..3 {
                    n[vi as usize][k] += f[k];
                }
            }
        }
        for v in n.iter_mut() {
            let l = (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt();
            if l > 1e-12 {
                *v = [v[0] / l, v[1] / l, v[2] / l];
            } else {
                *v = [0.0, 1.0, 0.0];
            }
        }
    }
    let base = p0 as u32;
    idx.extend(w.idx.iter().map(|&i| i + base));
    w.idx.len()
}

/// One part's final geometry as owned arrays (standard-mode writer).
fn finalize_mesh(
    part: &MeshPart,
    o: &GlbOptions,
) -> (Vec<[f32; 3]>, Vec<u32>, Option<Vec<[f32; 3]>>) {
    let mut w = Weld::default();
    let (mut pos, mut idx, mut norm) = (Vec::new(), Vec::new(), Vec::new());
    let want_n = o.include_normals && part.mode == MODE_TRIANGLES;
    finalize_append(
        part,
        o,
        &mut w,
        &mut pos,
        &mut idx,
        want_n.then_some(&mut norm),
    );
    (pos, idx, want_n.then_some(norm))
}

/// Little-endian byte view of a `u32` / `[f32; 3]` array (the GLB BIN layout),
/// so whole arrays are appended with one `memcpy` instead of per element.
#[cfg(target_endian = "little")]
fn u32_bytes(v: &[u32]) -> std::borrow::Cow<'_, [u8]> {
    // SAFETY: u32 has no padding and any bit pattern is a valid u8 sequence;
    // the slice covers exactly `len * 4` initialized bytes.
    std::borrow::Cow::Borrowed(unsafe {
        std::slice::from_raw_parts(v.as_ptr() as *const u8, v.len() * 4)
    })
}
#[cfg(target_endian = "little")]
fn vec3_bytes(v: &[[f32; 3]]) -> std::borrow::Cow<'_, [u8]> {
    // SAFETY: [f32; 3] is 12 bytes without padding; see `u32_bytes`.
    std::borrow::Cow::Borrowed(unsafe {
        std::slice::from_raw_parts(v.as_ptr() as *const u8, v.len() * 12)
    })
}
#[cfg(not(target_endian = "little"))]
fn u32_bytes(v: &[u32]) -> std::borrow::Cow<'_, [u8]> {
    std::borrow::Cow::Owned(v.iter().flat_map(|x| x.to_le_bytes()).collect())
}
#[cfg(not(target_endian = "little"))]
fn vec3_bytes(v: &[[f32; 3]]) -> std::borrow::Cow<'_, [u8]> {
    std::borrow::Cow::Owned(v.iter().flatten().flat_map(|x| x.to_le_bytes()).collect())
}

const COMP_U32: u32 = 5125;
const COMP_F32: u32 = 5126;
const TARGET_ELEMENT_ARRAY: u32 = 34963; // ELEMENT_ARRAY_BUFFER
const TARGET_ARRAY: u32 = 34962; // ARRAY_BUFFER

fn align4(n: usize) -> usize {
    (n + 3) & !3
}

/// One node in an explicit scene-graph tree (indices reference this same array;
/// `mesh` indexes into `parts`). Used by [`write_glb_tree`] to emit the decoded
/// NWD hierarchy verbatim — including empty containers and unplaced leaves.
pub struct SceneNode {
    pub name: String,
    pub mesh: Option<usize>,
    pub children: Vec<usize>,
}

/// Emit per-part geometry (bufferViews, accessors, meshes, materials) into one
/// shared binary buffer. Mesh `i` and material `i` correspond to `parts[i]`.
/// Returns `(bin, accessors, buffer_views, meshes, materials)` as JSON fragments.
fn emit_geometry(parts: &[MeshPart], o: &GlbOptions) -> (Vec<u8>, String, String, String, String) {
    let mut bin: Vec<u8> = Vec::new();
    let mut accessors = String::new();
    let mut buffer_views = String::new();
    let mut meshes = String::new();
    let mut materials = String::new();

    let mut acc_i = 0usize;
    let mut bv_i = 0usize;

    for (i, part) in parts.iter().enumerate() {
        let (fpos, fidx, fnorm) = finalize_mesh(part, o);
        // --- indices buffer view ---
        let idx_off = bin.len();
        for &idx in fidx.iter() {
            bin.extend_from_slice(&idx.to_le_bytes());
        }
        let idx_len = bin.len() - idx_off;
        while bin.len() % 4 != 0 {
            bin.push(0);
        }
        let idx_bv = bv_i;
        push_comma(&mut buffer_views, bv_i);
        buffer_views.push_str(&format!(
            r#"{{"buffer":0,"byteOffset":{idx_off},"byteLength":{idx_len},"target":{TARGET_ELEMENT_ARRAY}}}"#
        ));
        bv_i += 1;

        // --- positions buffer view ---
        let pos_off = bin.len();
        let mut min = [f32::INFINITY; 3];
        let mut max = [f32::NEG_INFINITY; 3];
        for p in fpos.iter() {
            for c in 0..3 {
                bin.extend_from_slice(&p[c].to_le_bytes());
                min[c] = min[c].min(p[c]);
                max[c] = max[c].max(p[c]);
            }
        }
        let pos_len = bin.len() - pos_off;
        while bin.len() % 4 != 0 {
            bin.push(0);
        }
        let pos_bv = bv_i;
        push_comma(&mut buffer_views, bv_i);
        buffer_views.push_str(&format!(
            r#"{{"buffer":0,"byteOffset":{pos_off},"byteLength":{pos_len},"target":{TARGET_ARRAY}}}"#
        ));
        bv_i += 1;

        // --- accessors ---
        let idx_acc = acc_i;
        push_comma(&mut accessors, acc_i);
        accessors.push_str(&format!(
            r#"{{"bufferView":{idx_bv},"componentType":{COMP_U32},"count":{},"type":"SCALAR"}}"#,
            fidx.len()
        ));
        acc_i += 1;
        let pos_acc = acc_i;
        push_comma(&mut accessors, acc_i);
        accessors.push_str(&format!(
            r#"{{"bufferView":{pos_bv},"componentType":{COMP_F32},"count":{},"type":"VEC3","min":[{},{},{}],"max":[{},{},{}]}}"#,
            fpos.len(),
            f(min[0]), f(min[1]), f(min[2]), f(max[0]), f(max[1]), f(max[2]),
        ));
        acc_i += 1;
        // --- optional NORMAL ---
        let mut norm_attr = String::new();
        if let Some(ns) = &fnorm {
            let n_off = bin.len();
            for nv in ns {
                for c in 0..3 {
                    bin.extend_from_slice(&nv[c].to_le_bytes());
                }
            }
            let n_len = bin.len() - n_off;
            push_comma(&mut buffer_views, bv_i);
            buffer_views.push_str(&format!(
                r#"{{"buffer":0,"byteOffset":{n_off},"byteLength":{n_len},"target":{TARGET_ARRAY}}}"#
            ));
            let n_bv = bv_i;
            bv_i += 1;
            push_comma(&mut accessors, acc_i);
            accessors.push_str(&format!(
                r#"{{"bufferView":{n_bv},"componentType":{COMP_F32},"count":{},"type":"VEC3"}}"#,
                ns.len()
            ));
            norm_attr = format!(r#","NORMAL":{acc_i}"#);
            acc_i += 1;
        }

        // --- material ---
        push_comma(&mut materials, i);
        let [r, g, b, a] = part.color;
        let blend = if a < 1.0 {
            r#","alphaMode":"BLEND""#
        } else {
            ""
        };
        materials.push_str(&format!(
            r#"{{"pbrMetallicRoughness":{{"baseColorFactor":[{},{},{},{}],"metallicFactor":0,"roughnessFactor":1}},"doubleSided":true{blend}}}"#,
            f(r), f(g), f(b), f(a),
        ));

        // --- mesh + node ---
        push_comma(&mut meshes, i);
        let mode_attr = if part.mode == 4 {
            String::new()
        } else {
            format!(r#","mode":{}"#, part.mode)
        };
        meshes.push_str(&format!(
            r#"{{"primitives":[{{"attributes":{{"POSITION":{pos_acc}{norm_attr}}},"indices":{idx_acc},"material":{i}{mode_attr}}}]}}"#
        ));
    }
    (bin, accessors, buffer_views, meshes, materials)
}

/// Build a GLB byte buffer from the given mesh parts, rebuilding the scene-graph
/// node tree from each part's ancestor `path` (empty path ⇒ a scene-root node).
pub fn write_glb(parts: &[MeshPart], o: &GlbOptions) -> Vec<u8> {
    let (bin, accessors, buffer_views, meshes, materials) = emit_geometry(parts, o);
    let mut nodes = String::new();
    let scene_nodes: String;

    // --- node tree ---
    // Mesh nodes occupy indices 0..parts.len(); group (ancestor) nodes follow.
    struct TNode {
        name: String,
        mesh: Option<usize>,
        children: Vec<usize>,
    }
    let mut tnodes: Vec<TNode> = parts
        .iter()
        .enumerate()
        .map(|(i, p)| TNode {
            name: p.name.clone(),
            mesh: Some(i),
            children: Vec::new(),
        })
        .collect();
    let mut prefix: std::collections::HashMap<Vec<String>, usize> =
        std::collections::HashMap::new();
    let mut roots: Vec<usize> = Vec::new();
    for (i, part) in parts.iter().enumerate() {
        // Ancestors = path without the mesh's own (last) name.
        if part.path.len() <= 1 {
            roots.push(i);
            continue;
        }
        let ancestors = &part.path[..part.path.len() - 1];
        let mut parent_idx: Option<usize> = None;
        for depth in 0..ancestors.len() {
            let key = ancestors[..=depth].to_vec();
            let idx = if let Some(&x) = prefix.get(&key) {
                x
            } else {
                tnodes.push(TNode {
                    name: ancestors[depth].clone(),
                    mesh: None,
                    children: Vec::new(),
                });
                let x = tnodes.len() - 1;
                prefix.insert(key, x);
                match parent_idx {
                    Some(p) => tnodes[p].children.push(x),
                    None => roots.push(x),
                }
                x
            };
            parent_idx = Some(idx);
        }
        tnodes[parent_idx.unwrap()].children.push(i);
    }
    for (i, n) in tnodes.iter().enumerate() {
        push_comma(&mut nodes, i);
        nodes.push('{');
        nodes.push_str(&format!(r#""name":{}"#, json_str(&n.name)));
        if let Some(m) = n.mesh {
            nodes.push_str(&format!(r#","mesh":{m}"#));
        }
        if !n.children.is_empty() {
            let kids: Vec<String> = n.children.iter().map(|c| c.to_string()).collect();
            nodes.push_str(&format!(r#","children":[{}]"#, kids.join(",")));
        }
        nodes.push('}');
    }
    scene_nodes = roots
        .iter()
        .map(|r| r.to_string())
        .collect::<Vec<_>>()
        .join(",");

    let json = format!(
        r#"{{"asset":{{"version":"2.0","generator":"nwd2glb"}},"scene":0,"scenes":[{{"nodes":[{scene_nodes}]}}],"nodes":[{nodes}],"meshes":[{meshes}],"materials":[{materials}],"accessors":[{accessors}],"bufferViews":[{buffer_views}],"buffers":[{{"byteLength":{}}}]}}"#,
        bin.len()
    );

    assemble(json.as_bytes(), &bin)
}

/// Build a GLB from mesh parts plus an **explicit** scene-graph tree (the decoded
/// NWD hierarchy): `tree[i]` becomes glTF node `i`, `scene.nodes = roots`. Lets
/// us emit the full Selection Tree — containers, named leaves, and unplaced
/// nodes — with each leaf's mesh + colour attached.
pub fn write_glb_tree(
    parts: &[MeshPart],
    tree: &[SceneNode],
    roots: &[usize],
    o: &GlbOptions,
) -> Vec<u8> {
    let (bin, accessors, buffer_views, meshes, materials) = emit_geometry(parts, o);
    let mut nodes = String::new();
    for (i, n) in tree.iter().enumerate() {
        push_comma(&mut nodes, i);
        nodes.push('{');
        // Empty name = intentionally anonymous (flattened wrapper); omit the
        // field so viewers fall back to the mesh label.
        let mut fields: Vec<String> = Vec::new();
        if !n.name.is_empty() {
            fields.push(format!(r#""name":{}"#, json_str(&n.name)));
        }
        if let Some(m) = n.mesh {
            fields.push(format!(r#""mesh":{m}"#));
        }
        if !n.children.is_empty() {
            let kids: Vec<String> = n.children.iter().map(|c| c.to_string()).collect();
            fields.push(format!(r#""children":[{}]"#, kids.join(",")));
        }
        nodes.push_str(&fields.join(","));
        nodes.push('}');
    }
    let scene_nodes = roots
        .iter()
        .map(|r| r.to_string())
        .collect::<Vec<_>>()
        .join(",");
    let json = format!(
        r#"{{"asset":{{"version":"2.0","generator":"nwd2glb"}},"scene":0,"scenes":[{{"nodes":[{scene_nodes}]}}],"nodes":[{nodes}],"meshes":[{meshes}],"materials":[{materials}],"accessors":[{accessors}],"bufferViews":[{buffer_views}],"buffers":[{{"byteLength":{}}}]}}"#,
        bin.len()
    );
    assemble(json.as_bytes(), &bin)
}

fn push_comma(s: &mut String, i: usize) {
    if i > 0 {
        s.push(',');
    }
}

/// Compact float formatting (avoid trailing-zero noise, keep it valid JSON).
fn f(v: f32) -> String {
    if v == v.trunc() && v.abs() < 1e15 {
        format!("{}", v as i64)
    } else {
        let s = format!("{v:.6}");
        s.trim_end_matches('0').trim_end_matches('.').to_string()
    }
}

fn json_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Wrap JSON + BIN chunks in the 12-byte GLB header.
fn assemble(json: &[u8], bin: &[u8]) -> Vec<u8> {
    let json_padded = align4(json.len());
    let bin_padded = align4(bin.len());
    let total = 12 + 8 + json_padded + 8 + bin_padded;

    let mut out = Vec::with_capacity(total);
    out.extend_from_slice(&0x46546C67u32.to_le_bytes()); // "glTF"
    out.extend_from_slice(&2u32.to_le_bytes());
    out.extend_from_slice(&(total as u32).to_le_bytes());

    // JSON chunk (space-padded).
    out.extend_from_slice(&(json_padded as u32).to_le_bytes());
    out.extend_from_slice(&0x4E4F534Au32.to_le_bytes()); // "JSON"
    out.extend_from_slice(json);
    out.resize(out.len() + (json_padded - json.len()), b' ');

    // BIN chunk (zero-padded).
    out.extend_from_slice(&(bin_padded as u32).to_le_bytes());
    out.extend_from_slice(&0x004E4942u32.to_le_bytes()); // "BIN\0"
    out.extend_from_slice(bin);
    out.resize(out.len() + (bin_padded - bin.len()), 0);

    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The merged writer streams its JSON by hand. It must be exactly what
    /// serde_json would write for the same document (object keys in string
    /// order: "10" < "100" < "9"), keep one draw range per element, and lay
    /// each colour mesh out as indices, then positions.
    #[test]
    fn merged_glb_json_is_canonical() {
        let (positions, indices) = box_mesh([0.0; 3], [1.0; 3]);
        let part = |color: [f32; 4], dx: f32| MeshPart {
            name: String::new(),
            positions: positions
                .iter()
                .map(|p| [p[0] + dx, p[1], p[2]])
                .collect::<Vec<_>>()
                .into(),
            indices: Arc::new(indices.clone()),
            mode: MODE_TRIANGLES,
            color,
            path: Vec::new(),
        };
        let red = [1.0, 0.0, 0.0, 1.0];
        let glass = [0.0, 0.0, 1.0, 0.5];
        let parts = vec![
            part(red, 0.0),
            part(red, 2.0),
            part(glass, 4.0),
            part(red, 6.0),
            part(red, 8.0),
        ];
        let items = vec![(9u32, 0usize), (10, 1), (10, 2), (100, 3), (100, 4)];
        let hier = vec![
            (9u32, "a \"quoted\" name".to_string(), Some(1u32)),
            (10, "b".to_string(), Some(1)),
            (100, "c".to_string(), Some(1)),
            (1, "root".to_string(), None),
        ];
        let (glb, mn, mx) = write_glb_merged(&parts, &items, &hier, &GlbOptions::default());
        assert_eq!(&glb[0..4], b"glTF");
        assert_eq!(
            u32::from_le_bytes(glb[8..12].try_into().unwrap()) as usize,
            glb.len()
        );
        let jl = u32::from_le_bytes(glb[12..16].try_into().unwrap()) as usize;
        let text = std::str::from_utf8(&glb[20..20 + jl]).unwrap().trim_end();
        let doc: serde_json::Value = serde_json::from_str(text).unwrap();
        assert_eq!(
            doc.to_string(),
            text,
            "hand-written JSON differs from serde's"
        );
        let ex = &doc["scenes"][0]["extras"];
        // red mesh: elements 9, 10, 100 — 36 indices per box, 100 has two boxes
        assert_eq!(
            ex["draw_ranges_node0"],
            serde_json::json!({"9":[0,36],"10":[36,36],"100":[72,72]})
        );
        assert_eq!(ex["draw_ranges_node1"], serde_json::json!({"10":[0,36]}));
        assert_eq!(
            ex["id_hierarchy"]["9"],
            serde_json::json!(["a \"quoted\" name", "1"])
        );
        assert_eq!(ex["id_hierarchy"]["1"], serde_json::json!(["root", "*"]));
        assert_eq!(doc["materials"][1]["alphaMode"], "BLEND");
        // BIN: [indices][positions] per mesh, 4 boxes of 8 welded vertices in red
        let bv = &doc["bufferViews"];
        assert_eq!(
            (bv[0]["byteOffset"].as_u64(), bv[0]["byteLength"].as_u64()),
            (Some(0), Some(4 * 36 * 4))
        );
        assert_eq!(
            (bv[1]["byteOffset"].as_u64(), bv[1]["byteLength"].as_u64()),
            (Some(576), Some(4 * 8 * 12))
        );
        assert_eq!(
            doc["buffers"][0]["byteLength"].as_u64().unwrap() as usize,
            glb.len() - 20 - jl - 8
        );
        assert_eq!((mn, mx), ([0.0, 0.0, 0.0], [9.0, 1.0, 1.0]));
        // the last red box's indices are rebased onto the merged vertex array
        let bin = &glb[20 + jl + 8..];
        let last = u32::from_le_bytes(bin[572..576].try_into().unwrap());
        assert!((24..32).contains(&last));
    }

    /// The writer must emit glTF-valid bufferView targets (34962 ARRAY_BUFFER,
    /// 34963 ELEMENT_ARRAY_BUFFER) — guards against the 34964 typo.
    #[test]
    fn buffer_view_targets_are_valid() {
        let (positions, indices) = box_mesh([0.0; 3], [1.0; 3]);
        let glb = write_glb(
            &[MeshPart {
                name: "t".into(),
                positions: positions.into(),
                indices: Arc::new(indices),
                mode: MODE_TRIANGLES,
                color: [0.5, 0.5, 0.5, 1.0],
                path: Vec::new(),
            }],
            &GlbOptions::default(),
        );
        assert_eq!(&glb[0..4], b"glTF");
        let json = String::from_utf8_lossy(&glb);
        assert!(json.contains("34962") && json.contains("34963"));
        assert!(!json.contains("34964"));
    }

    /// `unit_scale` is applied BEFORE the weld, so the weld grid is in output
    /// units: two corners 1.2 thousandths of a model unit apart sit in
    /// different cells of the model-unit grid, but in ONE 1 mm cell once the
    /// model (feet) is scaled to metres — the sliver triangle goes. The
    /// returned bounds are output units too; the default factor of 1 leaves
    /// the points bit-exact.
    #[test]
    fn unit_scale_is_applied_before_the_weld() {
        let part = MeshPart {
            name: String::new(),
            positions: vec![
                [0.0002, 0.0, 0.0],
                [0.0014, 0.0, 0.0],
                [0.0, 10.0, 0.0],
                [10.0, 0.0, 0.0],
            ]
            .into(),
            indices: Arc::new(vec![0, 1, 2, 0, 3, 2]),
            mode: MODE_TRIANGLES,
            color: [0.5, 0.5, 0.5, 1.0],
            path: Vec::new(),
        };
        let run = |unit_scale: f32| {
            let o = GlbOptions {
                unit_scale,
                ..Default::default()
            };
            let (mut pos, mut idx) = (Vec::new(), Vec::new());
            let n = finalize_append(&part, &o, &mut Weld::default(), &mut pos, &mut idx, None);
            let (_, mn, mx) = write_glb_merged(
                std::slice::from_ref(&part),
                &[(1, 0)],
                &[(1, "e".to_string(), None)],
                &o,
            );
            (n, pos, mn, mx)
        };
        let (n, pos, mn, mx) = run(1.0);
        assert_eq!((n, pos.len()), (6, 4));
        assert_eq!(pos[1], [0.0014, 0.0, 0.0]);
        assert_eq!((mn, mx), ([0.0, 0.0, 0.0], [10.0, 10.0, 0.0]));
        let (n, pos, mn, mx) = run(0.3048);
        assert_eq!((n, pos.len()), (3, 3), "the sliver's corners weld");
        assert_eq!(pos[2], [10.0 * 0.3048, 0.0, 0.0]);
        let top = 10.0 * 0.3048;
        assert_eq!((mn, mx), ([0.0, 0.0, 0.0], [top, top, 0.0]));
        let o = GlbOptions {
            unit_scale: 0.3048,
            ..Default::default()
        };
        assert_eq!(
            o.scale_bbox([-1.0, 0.0, 2.0], [1.0, 10.0, 4.0]),
            ([-0.3048, 0.0, 0.6096], [0.3048, top, 1.2192])
        );
        let empty = ([f32::INFINITY; 3], [f32::NEG_INFINITY; 3]);
        assert_eq!(o.scale_bbox(empty.0, empty.1), empty);
    }
}

/// A unit-ish axis-aligned box (8 verts, 12 triangles) spanning min..max.
pub fn box_mesh(min: [f32; 3], max: [f32; 3]) -> (Vec<[f32; 3]>, Vec<u32>) {
    let v = vec![
        [min[0], min[1], min[2]],
        [max[0], min[1], min[2]],
        [max[0], max[1], min[2]],
        [min[0], max[1], min[2]],
        [min[0], min[1], max[2]],
        [max[0], min[1], max[2]],
        [max[0], max[1], max[2]],
        [min[0], max[1], max[2]],
    ];
    let idx = vec![
        0, 2, 1, 0, 3, 2, // -z
        4, 5, 6, 4, 6, 7, // +z
        0, 1, 5, 0, 5, 4, // -y
        3, 7, 6, 3, 6, 2, // +y
        0, 4, 7, 0, 7, 3, // -x
        1, 2, 6, 1, 6, 5, // +x
    ];
    (v, idx)
}

// ---------------------------------------------------------------------------
// Merged (web3d) output — the rvm2glb "merged" contract:
// one mesh per colour with geometry baked to world space, per-element
// `draw_ranges_nodeK` + `id_hierarchy` scene extras (selection/highlight), and
// `asset.extras.web3dversion = 2`. One GLB per root site; see
// `convert::convert_split_merge`.
// ---------------------------------------------------------------------------

/// Build a MERGED GLB from `items` = `(element_id, part_index)` pairs.
///
/// Parts of one element must be adjacent in `items` (the caller sorts by
/// element id) so each element occupies ONE contiguous `[start, count]` range
/// of its colour-mesh's index buffer. `hier` = `(id, name, parent_id)` rows for
/// the `id_hierarchy` extra (`parent = None` ⇒ `"*"`, the root).
/// Returns `(glb_bytes, bbox_min, bbox_max)` (glTF Y-up space).
pub fn write_glb_merged(
    parts: &[MeshPart],
    items: &[(u32, usize)],
    hier: &[(u32, String, Option<u32>)],
    o: &GlbOptions,
) -> (Vec<u8>, [f32; 3], [f32; 3]) {
    use serde_json::{json, Value};
    // Group by colour (stable order of first appearance keeps output deterministic
    // given the caller's element-sorted items).
    let ckey = |c: [f32; 4]| -> [u8; 4] {
        [
            (c[0] * 255.0).round() as u8,
            (c[1] * 255.0).round() as u8,
            (c[2] * 255.0).round() as u8,
            (c[3] * 255.0).round() as u8,
        ]
    };
    let mut colors: Vec<[u8; 4]> = Vec::new();
    let mut buckets: std::collections::HashMap<[u8; 4], Vec<(u32, usize)>> =
        std::collections::HashMap::new();
    // Upper bound of the BIN size (the weld only ever removes vertices and
    // triangles): reserving it once means the output buffer never reallocates
    // while it fills. Untouched reserve costs address space, not memory.
    let mut bin_bound = 0usize;
    for &(eid, pi) in items {
        let p = &parts[pi];
        if p.indices.is_empty() {
            continue;
        }
        let k = ckey(p.color);
        if !buckets.contains_key(&k) {
            colors.push(k);
        }
        buckets.entry(k).or_default().push((eid, pi));
        let per_vertex = if o.include_normals { 24 } else { 12 };
        bin_bound += p.indices.len() * 4 + p.positions.len() * per_vertex;
    }

    // The GLB is built IN PLACE in one buffer: the BIN payload first (at
    // offset 0), then — once the JSON is known — the payload is shifted up by
    // the header + JSON length and those are written in front. Nothing is
    // copied into a second full-size buffer.
    let mut bin: Vec<u8> = Vec::new();
    let _ = bin.try_reserve_exact(bin_bound + 64 * 1024);
    let mut buffer_views: Vec<Value> = Vec::new();
    let mut accessors: Vec<Value> = Vec::new();
    let mut materials: Vec<Value> = Vec::new();
    let mut meshes: Vec<Value> = Vec::new();
    let mut nodes: Vec<Value> = Vec::new();
    let mut scene_nodes: Vec<usize> = Vec::new();
    // (extras key, JSON object text) per colour mesh.
    let mut draw_ranges: Vec<(String, Vec<u8>)> = Vec::new();
    let mut gmin = [f32::INFINITY; 3];
    let mut gmax = [f32::NEG_INFINITY; 3];

    // Finalized output of one batch of parts (weld etc. done on a worker).
    struct Batch {
        pos: Vec<[f32; 3]>,
        norm: Vec<[f32; 3]>,
        /// Batch-local indices (offset by the batch's first vertex on merge).
        idx: Vec<u32>,
        /// Index count contributed by each part of the batch, in order.
        counts: Vec<u32>,
        mn: [f32; 3],
        mx: [f32; 3],
    }
    let run_batch = |w: &mut Weld, batch: &[(u32, usize)]| -> Batch {
        let mut b = Batch {
            pos: Vec::new(),
            norm: Vec::new(),
            idx: Vec::new(),
            counts: Vec::with_capacity(batch.len()),
            mn: [f32::INFINITY; 3],
            mx: [f32::NEG_INFINITY; 3],
        };
        for &(_, pi) in batch {
            let n = finalize_append(
                &parts[pi],
                o,
                w,
                &mut b.pos,
                &mut b.idx,
                o.include_normals.then_some(&mut b.norm),
            );
            if o.include_normals {
                // non-triangle parts carry no computed normal
                b.norm.resize(b.pos.len(), [0.0, 1.0, 0.0]);
            }
            b.counts.push(n as u32);
        }
        for v in &b.pos {
            for k in 0..3 {
                b.mn[k] = b.mn[k].min(v[k]);
                b.mx[k] = b.mx[k].max(v[k]);
            }
        }
        b
    };
    // Parts per batch / batches per round. A round is finalized in parallel
    // and merged in order before the next starts, so the transient per-part
    // data stays a few MB however large the colour mesh is.
    const BATCH: usize = 256;
    const ROUND: usize = 64;
    // BIN layout per colour mesh: indices, then positions, then normals. The
    // index view's size is only known once every part is welded, but it is
    // bounded by the parts' raw index counts — so the index region is laid out
    // at that bound, positions are appended right behind it as the batches
    // arrive, and the (usually empty) slack between the two is closed with one
    // move at the end. No per-colour staging copy of the vertex data.
    let mut col_norm: Vec<[f32; 3]> = Vec::new();

    for (node_count, key) in colors.iter().enumerate() {
        let bucket = &buckets[key];
        col_norm.clear();
        let bv1_offset = bin.len();
        let idx_bound: usize = bucket
            .iter()
            .map(|&(_, pi)| parts[pi].indices.len() * 4)
            .sum();
        bin.resize(bv1_offset + idx_bound, 0);
        let pos_start = bin.len();
        let mut index_count = 0usize;
        let mut vert_count = 0usize;
        let mut mn = [f32::INFINITY; 3];
        let mut mx = [f32::NEG_INFINITY; 3];
        // element id -> [start, count] over this mesh's index buffer.
        let mut ranges: Vec<(u32, u32, u32)> = Vec::new();
        for round in bucket.chunks(BATCH * ROUND) {
            #[cfg(not(target_arch = "wasm32"))]
            let batches: Vec<Batch> = {
                use rayon::prelude::*;
                round
                    .par_chunks(BATCH)
                    .map_init(Weld::default, |w, b| run_batch(w, b))
                    .collect()
            };
            #[cfg(target_arch = "wasm32")]
            let batches: Vec<Batch> = {
                let mut w = Weld::default();
                round.chunks(BATCH).map(|b| run_batch(&mut w, b)).collect()
            };
            let mut it = round.iter();
            for mut b in batches {
                let base = vert_count as u32;
                for v in b.idx.iter_mut() {
                    *v += base;
                }
                let at = bv1_offset + index_count * 4;
                bin[at..at + b.idx.len() * 4].copy_from_slice(&u32_bytes(&b.idx));
                bin.extend_from_slice(&vec3_bytes(&b.pos));
                vert_count += b.pos.len();
                col_norm.extend_from_slice(&b.norm);
                for k in 0..3 {
                    mn[k] = mn[k].min(b.mn[k]);
                    mx[k] = mx[k].max(b.mx[k]);
                }
                for &n in &b.counts {
                    let (eid, _) = *it.next().expect("one count per part");
                    match ranges.last_mut() {
                        Some(r) if r.0 == eid => r.2 += n,
                        _ => ranges.push((eid, index_count as u32, n)),
                    }
                    index_count += n as usize;
                }
            }
        }
        if index_count == 0 {
            bin.truncate(bv1_offset);
            continue;
        }
        for k in 0..3 {
            gmin[k] = gmin[k].min(mn[k]);
            gmax[k] = gmax[k].max(mx[k]);
        }

        // Close the slack between the index view and the positions.
        let bv1_len = index_count * 4;
        let bv2_offset = bv1_offset + bv1_len;
        let bv2_len = vert_count * 12;
        if bv2_offset != pos_start {
            bin.copy_within(pos_start..pos_start + bv2_len, bv2_offset);
            bin.truncate(bv2_offset + bv2_len);
        }

        let bv1 = buffer_views.len();
        buffer_views
            .push(json!({"buffer":0,"byteOffset":bv1_offset,"byteLength":bv1_len,"target":34963}));
        let bv2 = buffer_views.len();
        buffer_views
            .push(json!({"buffer":0,"byteOffset":bv2_offset,"byteLength":bv2_len,"target":34962}));
        let acc1 = accessors.len();
        accessors.push(json!({"bufferView":bv1,"byteOffset":0,"componentType":5125,
            "count":index_count,"type":"SCALAR","min":[0],"max":[vert_count.saturating_sub(1)]}));
        let acc2 = accessors.len();
        accessors.push(json!({"bufferView":bv2,"byteOffset":0,"componentType":5126,
            "count":vert_count,"type":"VEC3","min":[mn[0],mn[1],mn[2]],"max":[mx[0],mx[1],mx[2]]}));
        let norm_acc: Option<usize> = if o.include_normals {
            let bvn_offset = bin.len();
            bin.extend_from_slice(&vec3_bytes(&col_norm));
            let bvn_len = bin.len() - bvn_offset;
            let bvn = buffer_views.len();
            buffer_views.push(
                json!({"buffer":0,"byteOffset":bvn_offset,"byteLength":bvn_len,"target":34962}),
            );
            let a = accessors.len();
            accessors.push(json!({"bufferView":bvn,"byteOffset":0,"componentType":5126,
                "count":vert_count,"type":"VEC3"}));
            Some(a)
        } else {
            None
        };

        let mat = materials.len();
        let c = [
            key[0] as f32 / 255.0,
            key[1] as f32 / 255.0,
            key[2] as f32 / 255.0,
            key[3] as f32 / 255.0,
        ];
        let mut m = json!({"pbrMetallicRoughness":{"baseColorFactor":[c[0],c[1],c[2],c[3]],
            "metallicFactor":0,"roughnessFactor":1},"doubleSided":true});
        if key[3] < 255 {
            m["alphaMode"] = json!("BLEND");
        }
        materials.push(m);

        let mesh_idx = meshes.len();
        let mut attrs = json!({"POSITION": acc2});
        if let Some(na) = norm_acc {
            attrs["NORMAL"] = json!(na);
        }
        meshes.push(json!({"primitives":[{"attributes":attrs,"indices":acc1,
            "material":mat,"mode":4}]}));
        let n_idx = nodes.len();
        nodes.push(json!({"mesh":mesh_idx,"name":format!("node{node_count}")}));
        scene_nodes.push(n_idx);

        // {"<eid>":[start,count],…} — keys in string order, last range of a
        // repeated id wins (what a JSON object map gives).
        let mut order: Vec<usize> = (0..ranges.len()).collect();
        order.sort_by_key(|&i| dec_key(ranges[i].0)); // stable: later dup stays later
        let mut rec: Vec<u8> = Vec::with_capacity(ranges.len() * 24 + 2);
        rec.push(b'{');
        let mut first = true;
        for (n, &i) in order.iter().enumerate() {
            let (eid, start, count) = ranges[i];
            if order.get(n + 1).is_some_and(|&j| ranges[j].0 == eid) {
                continue;
            }
            if !first {
                rec.push(b',');
            }
            first = false;
            use std::io::Write;
            let _ = write!(rec, "\"{eid}\":[{start},{count}]");
        }
        rec.push(b'}');
        draw_ranges.push((format!("draw_ranges_node{node_count}"), rec));
    }
    drop(col_norm);
    while bin.len() % 4 != 0 {
        bin.push(0);
    }

    // ── JSON chunk, written straight to bytes ──────────────────────────────
    // Byte-for-byte what `serde_json::json!({...}).to_string()` produces
    // (object keys in string order, compact) — but the two big maps
    // (`draw_ranges_*`, `id_hierarchy`: one entry per element / tree node)
    // are streamed instead of being built as a `Value` tree first.
    fn put(out: &mut Vec<u8>, v: &impl serde::Serialize) {
        serde_json::to_writer(out, v).expect("JSON to memory cannot fail");
    }
    let mut js: Vec<u8> = Vec::with_capacity(
        4096 + draw_ranges.iter().map(|d| d.1.len() + 32).sum::<usize>() + hier.len() * 48,
    );
    js.extend_from_slice(b"{\"accessors\":");
    put(&mut js, &accessors);
    js.extend_from_slice(b",\"asset\":");
    put(
        &mut js,
        &json!({"version":"2.0","generator":"nwd2glb","extras":{"web3dversion":2}}),
    );
    js.extend_from_slice(b",\"bufferViews\":");
    put(&mut js, &buffer_views);
    js.extend_from_slice(b",\"buffers\":");
    put(&mut js, &json!([{"byteLength": bin.len()}]));
    js.extend_from_slice(b",\"materials\":");
    put(&mut js, &materials);
    js.extend_from_slice(b",\"meshes\":");
    put(&mut js, &meshes);
    js.extend_from_slice(b",\"nodes\":");
    put(&mut js, &nodes);
    js.extend_from_slice(b",\"scene\":0,\"scenes\":[{\"extras\":{");
    draw_ranges.sort_by(|a, b| a.0.cmp(&b.0));
    for (name, rec) in &draw_ranges {
        put(&mut js, name);
        js.push(b':');
        js.extend_from_slice(rec);
        js.push(b',');
    }
    js.extend_from_slice(b"\"id_hierarchy\":{");
    {
        let mut order: Vec<usize> = (0..hier.len()).collect();
        order.sort_by_key(|&i| dec_key(hier[i].0));
        let mut first = true;
        for (n, &i) in order.iter().enumerate() {
            let (id, name, parent) = &hier[i];
            if order.get(n + 1).is_some_and(|&j| hier[j].0 == *id) {
                continue; // repeated id: the last row wins
            }
            if !first {
                js.push(b',');
            }
            first = false;
            use std::io::Write;
            let _ = write!(js, "\"{id}\":[");
            put(&mut js, name);
            match parent {
                Some(p) => {
                    let _ = write!(js, ",\"{p}\"]");
                }
                None => js.extend_from_slice(b",\"*\"]"),
            }
        }
    }
    js.extend_from_slice(b"}},\"nodes\":");
    put(&mut js, &scene_nodes);
    js.extend_from_slice(b"}]}");

    // ── assemble in place: [12 header][8][JSON + pad][8][BIN] ──────────────
    let json_padded = align4(js.len());
    let bin_len = bin.len(); // already 4-aligned
    let prefix = 12 + 8 + json_padded + 8;
    let total = prefix + bin_len;
    bin.reserve_exact(prefix);
    bin.resize(total, 0);
    bin.copy_within(0..bin_len, prefix);
    let mut head: Vec<u8> = Vec::with_capacity(prefix);
    head.extend_from_slice(&0x46546C67u32.to_le_bytes()); // "glTF"
    head.extend_from_slice(&2u32.to_le_bytes());
    head.extend_from_slice(&(total as u32).to_le_bytes());
    head.extend_from_slice(&(json_padded as u32).to_le_bytes());
    head.extend_from_slice(&0x4E4F534Au32.to_le_bytes()); // "JSON"
    head.extend_from_slice(&js);
    head.resize(20 + json_padded, b' ');
    head.extend_from_slice(&(bin_len as u32).to_le_bytes());
    head.extend_from_slice(&0x004E4942u32.to_le_bytes()); // "BIN\0"
    bin[..prefix].copy_from_slice(&head);
    (bin, gmin, gmax)
}

/// Sort key that orders `u32` ids like their DECIMAL STRINGS (the order a
/// JSON object map keyed by `id.to_string()` serializes in): the digits,
/// left-aligned and zero-byte padded.
fn dec_key(v: u32) -> [u8; 10] {
    let mut digits = [0u8; 10];
    let mut n = 0;
    let mut x = v;
    loop {
        digits[n] = b'0' + (x % 10) as u8;
        n += 1;
        x /= 10;
        if x == 0 {
            break;
        }
    }
    let mut key = [0u8; 10];
    for i in 0..n {
        key[i] = digits[n - 1 - i];
    }
    key
}
